export type CheapTtsVoice = {
  id: string;
  name: string;
  language: string;
  useCase: string;
};

type RuntimeVoice = CheapTtsVoice & { asset: string };

export type CheapTtsProgress = {
  stage: "session" | "model" | "synthesis";
  progress: number | null;
};

/** Extra silence inserted at punctuation boundaries, in seconds (0–2).
 *  Omit or leave a field at 0 to keep the model's own pause, which is the
 *  default and the fastest path — a raised value makes the server cut the audio
 *  at that boundary so real silence can follow. */
export type CheapTtsPauses = {
  sentence?: number;
  comma?: number;
  ellipsis?: number;
  paragraph?: number;
};

export type SynthesizeOptions = {
  text: string;
  voice: string;
  rate?: number;
  pauses?: CheapTtsPauses;
  onProgress?: (event: CheapTtsProgress) => void;
};

export type LoadVoiceOptions = {
  voice: string;
  onProgress?: (event: CheapTtsProgress) => void;
  signal?: AbortSignal;
};

export type SynthesisResult = {
  audio: Blob;
  arrayBuffer: ArrayBuffer;
  seconds: number;
  voice: CheapTtsVoice;
};

export type CheapTtsOptions = {
  publishableKey: string;
  apiBase?: string;
  workerUrl?: string;
  vendorBase?: string;
  telemetry?: boolean;
  /** Identifies an official wrapper in operational telemetry. Defaults to browser. */
  runtime?: "browser" | "react";
};

export type CheapTtsErrorCode =
  | "method_not_allowed" | "origin_required" | "invalid_publishable_key_or_origin"
  | "invalid_server_key" | "invalid_session" | "invalid_credentials"
  | "subscription_required" | "invalid_content_type" | "request_too_large"
  | "rate_limited" | "invalid_json" | "text_required" | "text_too_long"
  | "voice_required" | "unknown_voice" | "invalid_request"
  | "invalid_telemetry_event" | "invalid_telemetry" | "authentication_unavailable"
  | "catalog_unavailable" | "session_unavailable" | "prepare_failed";

type ApiErrorBody = { error?: string; code?: CheapTtsErrorCode; request_id?: string };

export class CheapTtsApiError extends Error {
  readonly status: number;
  readonly code?: CheapTtsErrorCode;
  readonly requestId?: string;

  constructor(message: string, status: number, code?: CheapTtsErrorCode, requestId?: string) {
    super(message);
    this.name = "CheapTtsApiError";
    this.status = status;
    this.code = code;
    this.requestId = requestId;
  }
}

type Session = {
  token: string;
  expiresAt: string;
  runtime: { modelBase: string };
  voices: RuntimeVoice[];
};

type WorkerJob = {
  resolve: (result: { wav: ArrayBuffer; seconds: number }) => void;
  reject: (error: Error) => void;
  onProgress?: (event: CheapTtsProgress) => void;
};

type FailureStage = "session" | "catalog" | "model" | "prepare" | "synthesis" | "unknown";
type TaggedFailure = { cheapTtsFailure: true; stage: FailureStage; error: unknown };

const DB_NAME = "cheap-tts-browser-sdk";
const STORE_NAME = "models";

function trimSlash(value: string): string {
  return value.replace(/\/$/, "");
}

function openDb(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, 1);
    request.onupgradeneeded = () => request.result.createObjectStore(STORE_NAME);
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error ?? new Error("Unable to open model cache"));
  });
}

async function cachedModel(key: string): Promise<ArrayBuffer | null> {
  try {
    const db = await openDb();
    return await new Promise((resolve, reject) => {
      const request = db.transaction(STORE_NAME, "readonly").objectStore(STORE_NAME).get(key);
      request.onsuccess = () => resolve(request.result instanceof ArrayBuffer ? request.result : null);
      request.onerror = () => reject(request.error);
    });
  } catch {
    return null;
  }
}

async function cacheModel(key: string, model: ArrayBuffer): Promise<void> {
  try {
    const db = await openDb();
    await new Promise<void>((resolve, reject) => {
      const request = db.transaction(STORE_NAME, "readwrite").objectStore(STORE_NAME).put(model, key);
      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  } catch {
    // Private browsing and storage quotas must not prevent synthesis.
  }
}

async function fetchBuffer(
  url: string,
  onProgress?: (progress: number | null) => void,
  signal?: AbortSignal,
): Promise<ArrayBuffer> {
  const response = await fetch(url, { signal });
  if (!response.ok) throw new Error(`Model download failed (HTTP ${response.status})`);
  const total = Number(response.headers.get("Content-Length") ?? 0);
  if (!response.body) return response.arrayBuffer();
  const reader = response.body.getReader();
  const chunks: Uint8Array[] = [];
  let loaded = 0;
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    chunks.push(value);
    loaded += value.byteLength;
    onProgress?.(total > 0 ? loaded / total : null);
  }
  const output = new Uint8Array(loaded);
  let offset = 0;
  for (const chunk of chunks) {
    output.set(chunk, offset);
    offset += chunk.byteLength;
  }
  return output.buffer;
}

export class CheapTts {
  private readonly publishableKey: string;
  private readonly apiBase: string;
  private readonly workerUrl: string;
  private readonly wasmPaths: { mjs: string; wasm: string };
  private readonly telemetryEnabled: boolean;
  private readonly runtime: "browser" | "react";
  private session: Session | null = null;
  private sessionPromise: Promise<Session> | null = null;
  private worker: Worker | null = null;
  private workerReady: Promise<void> | null = null;
  private loadedAsset: string | null = null;
  private jobs = new Map<number, WorkerJob>();
  private nextJobId = 1;
  private queue: Promise<unknown> = Promise.resolve();
  private modelQueue: Promise<unknown> = Promise.resolve();

  constructor(options: CheapTtsOptions) {
    if (typeof window === "undefined") throw new Error("@cheap-tts/browser-sdk only runs in a browser");
    if (!options?.publishableKey?.startsWith("pk_")) throw new Error("A publishable key is required");
    this.publishableKey = options.publishableKey;
    this.apiBase = trimSlash(options.apiBase ?? "https://www.cheap-tts.com");
    this.workerUrl = options.workerUrl ?? new URL("./tts-worker.js", import.meta.url).href;
    this.telemetryEnabled = options.telemetry !== false;
    this.runtime = options.runtime === "react" ? "react" : "browser";
    const vendorBase = options.vendorBase ? `${trimSlash(options.vendorBase)}/` : null;
    this.wasmPaths = {
      mjs: vendorBase
        ? `${vendorBase}ort-wasm-simd-threaded.mjs`
        : new URL("./vendor/ort-wasm-simd-threaded.mjs", import.meta.url).href,
      wasm: vendorBase
        ? `${vendorBase}ort-wasm-simd-threaded.wasm`
        : new URL("./vendor/ort-wasm-simd-threaded.wasm", import.meta.url).href,
    };
  }

  async voices(): Promise<CheapTtsVoice[]> {
    const session = await this.ensureSession();
    return session.voices.map(({ asset: _asset, ...voice }) => voice);
  }

  async loadVoice(options: LoadVoiceOptions): Promise<CheapTtsVoice> {
    const session = await this.ensureSession();
    const voice = session.voices.find((candidate) => candidate.id === options.voice);
    if (!voice) throw new Error(`Unknown voice: ${options.voice}`);
    await this.queueModel(session, voice, options.onProgress, options.signal);
    const { asset: _asset, ...publicVoice } = voice;
    return publicVoice;
  }

  synthesize(options: SynthesizeOptions): Promise<SynthesisResult> {
    const run = () => this.runSynthesis(options);
    const result = this.queue.then(run, run);
    this.queue = result.catch(() => undefined);
    return result;
  }

  destroy(): void {
    this.worker?.terminate();
    this.worker = null;
    this.workerReady = null;
    this.loadedAsset = null;
    for (const job of this.jobs.values()) job.reject(new Error("Cheap TTS client was destroyed"));
    this.jobs.clear();
  }

  private async runSynthesis(options: SynthesizeOptions): Promise<SynthesisResult> {
    if (!options.text?.trim()) throw new Error("text is required");
    const startedAt = performance.now();
    const clientRequestId = globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random().toString(36).slice(2)}`;
    let session: Session | null = null;
    try {
      options.onProgress?.({ stage: "session", progress: null });
      session = await this.ensureSession();
      const voice = session.voices.find((candidate) => candidate.id === options.voice);
      if (!voice) throw this.tagFailure("catalog", new Error(`Unknown voice: ${options.voice}`));
      const [prepared] = await Promise.all([
        this.prepare(session, options.text, voice.id, options.pauses).catch((error) => { throw this.tagFailure("prepare", error); }),
        this.queueModel(session, voice, options.onProgress).catch((error) => { throw this.tagFailure("model", error); }),
      ]);
      const worker = this.worker;
      if (!worker) throw this.tagFailure("synthesis", new Error("TTS worker is unavailable"));
      const id = this.nextJobId++;
      const result = await new Promise<{ wav: ArrayBuffer; seconds: number }>((resolve, reject) => {
        this.jobs.set(id, { resolve, reject, onProgress: options.onProgress });
        worker.postMessage({ type: "synthesize", id, prepared, rate: options.rate ?? 1 });
      }).catch((error) => { throw this.tagFailure("synthesis", error); });
      const { asset: _asset, ...publicVoice } = voice;
      this.sendTelemetry(session, {
        event: "sdk_synthesis_succeeded", request_id: clientRequestId,
        duration_ms: performance.now() - startedAt, audio_seconds: result.seconds,
        characters: options.text.length, voice: voice.id,
      });
      return {
        audio: new Blob([result.wav], { type: "audio/wav" }),
        arrayBuffer: result.wav,
        seconds: result.seconds,
        voice: publicVoice,
      };
    } catch (caught) {
      const failure = this.isTaggedFailure(caught) ? caught : this.tagFailure(session ? "unknown" : "session", caught);
      if (session) this.sendTelemetry(session, {
        event: "sdk_synthesis_failed", request_id: clientRequestId,
        duration_ms: performance.now() - startedAt, characters: options.text.length,
        voice: options.voice, failure_stage: failure.stage,
        error_code: this.telemetryErrorCode(failure.stage, failure.error),
      });
      throw failure.error;
    }
  }

  private tagFailure(stage: FailureStage, error: unknown): TaggedFailure {
    return { cheapTtsFailure: true, stage, error };
  }

  private isTaggedFailure(value: unknown): value is TaggedFailure {
    return Boolean(value && typeof value === "object" && (value as TaggedFailure).cheapTtsFailure === true);
  }

  private telemetryErrorCode(stage: FailureStage, error: unknown): string {
    if (error instanceof DOMException && error.name === "AbortError") return "aborted";
    if (stage === "catalog" || stage === "session") return "catalog_failed";
    if (stage === "model") return "model_failed";
    if (stage === "prepare") return "prepare_failed";
    if (stage === "synthesis") return "synthesis_failed";
    return "unknown_error";
  }

  private sendTelemetry(session: Session, body: Record<string, unknown>): void {
    if (!this.telemetryEnabled) return;
    void fetch(`${this.apiBase}/api/sdk/v1/telemetry`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${session.token}`,
        "Content-Type": "application/json",
        "X-Cheap-TTS-Runtime": this.runtime,
      },
      body: JSON.stringify(body),
      keepalive: true,
    }).catch(() => undefined);
  }

  private async ensureSession(): Promise<Session> {
    if (this.session && Date.parse(this.session.expiresAt) - Date.now() > 30_000) return this.session;
    if (this.sessionPromise) return this.sessionPromise;
    this.sessionPromise = fetch(`${this.apiBase}/api/sdk/v1/session`, {
      method: "POST",
      headers: {
        "X-Publishable-Key": this.publishableKey,
        "X-Cheap-TTS-Runtime": this.runtime,
      },
    })
      .then(async (response) => {
        const body = await response.json().catch(() => ({})) as Session & ApiErrorBody;
        if (!response.ok) throw new CheapTtsApiError(
          body.error ?? `Session failed (HTTP ${response.status})`,
          response.status,
          body.code,
          body.request_id ?? response.headers.get("X-Request-ID") ?? undefined,
        );
        this.session = body;
        return body;
      })
      .finally(() => { this.sessionPromise = null; });
    return this.sessionPromise;
  }

  private async prepare(session: Session, text: string, voice: string, pauses?: CheapTtsPauses): Promise<unknown> {
    const response = await fetch(`${this.apiBase}/api/sdk/v1/prepare`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${session.token}`,
        "Content-Type": "application/json",
        "X-Cheap-TTS-Runtime": this.runtime,
      },
      // Omitted when unset so the request stays byte-identical for callers that
      // never touch pauses.
      body: JSON.stringify(pauses ? { text, voice, pauses } : { text, voice }),
    });
    const body = await response.json().catch(() => ({})) as ApiErrorBody;
    if (!response.ok) throw new CheapTtsApiError(
      body.error ?? `Text preparation failed (HTTP ${response.status})`,
      response.status,
      body.code,
      body.request_id ?? response.headers.get("X-Request-ID") ?? undefined,
    );
    return body;
  }

  private ensureWorker(): Promise<void> {
    if (this.workerReady) return this.workerReady;
    const boot = new Promise<void>((resolve, reject) => {
      const worker = new Worker(this.workerUrl, { type: "module" });
      this.worker = worker;
      const onBoot = (event: MessageEvent) => {
        const type = (event.data as { type?: string }).type;
        if (type === "ready") {
          worker.removeEventListener("message", onBoot);
          resolve();
        } else if (type === "init-error") {
          worker.removeEventListener("message", onBoot);
          reject(new Error((event.data as { message?: string }).message ?? "Worker initialization failed"));
        }
      };
      worker.addEventListener("message", onBoot);
      worker.addEventListener("message", (event: MessageEvent) => this.onWorkerMessage(event));
      worker.postMessage({ type: "init", wasmPaths: this.wasmPaths });
    });
    const ready = boot.catch((error) => {
      this.worker?.terminate();
      this.worker = null;
      this.workerReady = null;
      throw error;
    });
    this.workerReady = ready;
    return ready;
  }

  private async ensureModel(
    session: Session,
    voice: RuntimeVoice,
    onProgress?: (event: CheapTtsProgress) => void,
    signal?: AbortSignal,
  ): Promise<void> {
    signal?.throwIfAborted();
    await this.ensureWorker();
    if (this.loadedAsset === voice.asset) return;
    const base = `${trimSlash(session.runtime.modelBase)}/${voice.asset}`;
    const [configResponse, fromCache] = await Promise.all([
      fetch(`${base}.onnx.json`, { signal }),
      cachedModel(voice.asset),
    ]);
    if (!configResponse.ok) throw new Error(`Voice configuration failed (HTTP ${configResponse.status})`);
    const config = await configResponse.json();
    let model = fromCache;
    if (!model) {
      model = await fetchBuffer(
        `${base}.onnx`,
        (progress) => onProgress?.({ stage: "model", progress }),
        signal,
      );
      await cacheModel(voice.asset, model);
    } else {
      onProgress?.({ stage: "model", progress: 1 });
    }
    const worker = this.worker;
    if (!worker) throw new Error("TTS worker is unavailable");
    signal?.throwIfAborted();
    await new Promise<void>((resolve, reject) => {
      const onLoad = (event: MessageEvent) => {
        const data = event.data as { type?: string; message?: string };
        if (data.type === "model-loaded") {
          worker.removeEventListener("message", onLoad);
          resolve();
        } else if (data.type === "init-error") {
          worker.removeEventListener("message", onLoad);
          reject(new Error(data.message ?? "Voice loading failed"));
        }
      };
      worker.addEventListener("message", onLoad);
      worker.postMessage({ type: "load-model", model, config }, [model]);
    });
    this.loadedAsset = voice.asset;
  }

  private queueModel(
    session: Session,
    voice: RuntimeVoice,
    onProgress?: (event: CheapTtsProgress) => void,
    signal?: AbortSignal,
  ): Promise<void> {
    const run = () => this.ensureModel(session, voice, onProgress, signal);
    const result = this.modelQueue.then(run, run);
    this.modelQueue = result.catch(() => undefined);
    return result;
  }

  private onWorkerMessage(event: MessageEvent): void {
    const data = event.data as {
      type?: string;
      id?: number;
      done?: number;
      total?: number;
      wav?: ArrayBuffer;
      seconds?: number;
      message?: string;
    };
    if (data.id == null) return;
    const job = this.jobs.get(data.id);
    if (!job) return;
    if (data.type === "progress") {
      const progress = data.total ? (data.done ?? 0) / data.total : null;
      job.onProgress?.({ stage: "synthesis", progress });
    } else if (data.type === "result" && data.wav) {
      this.jobs.delete(data.id);
      job.resolve({ wav: data.wav, seconds: data.seconds ?? 0 });
    } else if (data.type === "job-error") {
      this.jobs.delete(data.id);
      job.reject(new Error(data.message ?? "Synthesis failed"));
    }
  }
}

export default CheapTts;
